    const pageRow=(pg,i)=>`<div class="wb19-section-card wb19-page-structure-card ${pg.enabled===false?'disabled':''}" data-page-id="${pg.id}"><div class="section-drag" aria-hidden="true">↗</div><div class="section-card-main"><div class="section-card-title"><span class="section-order">${String(i+1).padStart(2,'0')}</span><b>${esc(pg.label)}</b></div><small>Dedicated award page</small><div class="section-card-meta"><span class="page-source-chip">Award page</span><span class="section-status-chip">${pg.enabled===false?'Inactive':'Live page'}</span><label class="section-nav-control ${pg.showInNav===false?'off':''}" title="Show in public navigation"><input type="checkbox" data-page-nav="${pg.id}" ${pg.enabled!==false&&pg.showInNav!==false?'checked':''} ${pg.enabled===false?'disabled':''}><span>Nav</span></label></div></div><div class="section-card-actions"><label class="section-toggle" title="Enable / disable page"><input type="checkbox" data-page-toggle="${pg.id}" ${pg.enabled!==false?'checked':''}><i></i></label><button type="button" class="section-customize-btn" data-edit-page="${pg.id}">Customize</button></div></div>`;
    box.innerHTML=`<section class="site-structure-group"><div class="site-structure-head"><div><small>HOMEPAGE</small><b>Homepage sections</b></div><span>${active.length} live</span></div><div class="section-group-label">Active sections</div>${active.map((x,i)=>row(x,i)).join('')}${inactive.length?`<div class="section-group-label inactive">Inactive sections · kept below</div>${inactive.map((x,i)=>row(x,active.length+i)).join('')}`:''}</section><section class="site-structure-group"><div class="site-structure-head"><div><small>AWARD PAGES</small><b>Dedicated navigation pages</b></div><span>${activePages.length} live</span></div><div class="section-group-label">Active pages</div>${activePages.map((x,i)=>pageRow(x,i)).join('')}${inactivePages.length?`<div class="section-group-label inactive">Inactive pages</div>${inactivePages.map((x,i)=>pageRow(x,activePages.length+i)).join('')}`:''}</section>`;
