    box.querySelectorAll('[data-page-toggle]').forEach(el=>el.addEventListener('change',()=>{const pg=pageBy(el.dataset.pageToggle);pg.enabled=el.checked;if(el.checked&&pg.showInNav==null)pg.showInNav=true;if(pg.id==='rewards')state.pages.rewards.enabled=el.checked;markDirty();renderSectionManager();renderNavManager();toast(el.checked?`${pg.label} page activated`:`${pg.label} page deactivated`)}));
    box.querySelectorAll('[data-page-nav]').forEach(el=>el.addEventListener('change',()=>{const pg=pageBy(el.dataset.pageNav);pg.showInNav=el.checked;markDirty();renderSectionManager();renderNavManager();toast(el.checked?`${pg.label} added to navigation`:`${pg.label} removed from navigation`)}));
    box.querySelectorAll('[data-edit-page]').forEach(b=>b.addEventListener('click',()=>openPublicPageDesigner(b.dataset.editPage)));
    box.querySelectorAll('[data-edit-section]').forEach(b=>b.addEventListener('click',()=>openSectionDesigner(b.dataset.editSection,'content')));
