  /* Generic entity editors */
  function openEntityEditor(kind,index,groupKind=''){
    entityContext={kind,index,groupKind};const modal=$('entityModal'),body=$('entityBody');$('entityEyebrow').textContent=index==null?'ADD':'EDIT';
    let html='';
    if(kind==='speaker'){
      const s=speakerSection(),p=index==null?{name:'',role:'',company:'',groupId:s.speakerGroups[0]?.id||'',status:true}:s.speakers[index];$('entityTitle').textContent=index==null?'Add speaker':'Edit speaker';$('entitySubtitle').textContent='Manage profile details. Use the Photo button in the list for smart image editing.';
      html=`${formField('Name','name',p.name,true)}${formField('Role / designation','role',p.role)}${formField('Company','company',p.company)}${selectField('Speaker group','groupId',p.groupId,s.speakerGroups.map(g=>[g.id,g.name]))}${toggleField('Active speaker','Show this speaker on the public site.','status',p.status!==false)}`;
    } else if(kind==='agenda'){
      const s=sectionBy('agenda'),x=index==null?{title:'',start:'',end:'',groupId:s.agendaGroups[0]?.id||'',speakerIds:[],summary:'',points:'',status:true}:s.agenda[index];$('entityTitle').textContent=index==null?'Add Agenda':'Edit Agenda';$('entitySubtitle').textContent='Create a complete session with timing, group, speakers and description.';const speakers=speakerSection().speakers;
      html=`${formField('Title','title',x.title,true)}<div class="wb19-two">${formField('Session Start Date & Time','start',x.start,true,'datetime-local')}${formField('Session End Date & Time','end',x.end,true,'datetime-local')}</div>${selectField('Agenda Group','groupId',x.groupId,s.agendaGroups.map(g=>[g.id,g.name]))}<label class="wb19-field"><span>Speakers</span><div class="entity-checkbox-grid">${speakers.map(p=>`<label><input type="checkbox" name="speakerIds" value="${p.id}" ${(x.speakerIds||[]).includes(p.id)?'checked':''}><span>${esc(p.name)}</span></label>`).join('')}</div></label>${textareaField('Description Summary','summary',x.summary)}${textareaField('Description Points · one per line','points',x.points)}${toggleField('Active agenda item','Show this session on the public site.','status',x.status!==false)}`;
    } else if(kind==='gallery'){
      const s=sectionBy('glimpse'),x=s.images[index];$('entityTitle').textContent='Edit gallery image';$('entitySubtitle').textContent='Add a title, social handle and image group.';html=`${formField('Title','title',x.title,true)}${formField('Social Handle / caption','socialHandle',x.socialHandle)}${selectField('Image Group','groupId',x.groupId,s.galleryGroups.map(g=>[g.id,g.name]))}${formField('Weightage','weight',x.weight,false,'number')}${toggleField('Active image','Show this image in the public gallery.','status',x.status!==false)}`;
    } else if(kind==='contact'){
      const s=sectionBy('contact'),c=index==null?{name:'',email:'',phone:'',company:'',designation:'',groupId:s.contactGroups[0]?.id||'',status:true}:s.contacts[index];$('entityTitle').textContent=index==null?'Add New Contact':'Edit Contact';$('entitySubtitle').textContent='Add complete visitor-facing contact information.';html=`${formField('Name','name',c.name,true)}${formField('Email','email',c.email,true,'email')}${formField('Phone','phone',c.phone)}${formField('Company','company',c.company)}${formField('Designation / role','designation',c.designation)}${selectField('Contact Group','groupId',c.groupId,s.contactGroups.map(g=>[g.id,g.name]))}${toggleField('Active contact','Show this contact on the public site.','status',c.status!==false)}`;
    } else if(kind==='regfield'){
      const arr=state.form.customFields||[],f=index==null?{label:'',name:'',type:'text',placeholder:'',required:false,active:true,options:''}:arr[index];$('entityTitle').textContent=index==null?'Add registration field':'Edit registration field';$('entitySubtitle').textContent='Create a field for the hero or popup registration experience.';html=`${formField('Field label','label',f.label,true)}${formField('Field key','name',f.name||'',false)}${selectField('Field type','type',f.type||'text',[['text','Short text'],['email','Email'],['phone','Phone'],['number','Number'],['textarea','Long answer'],['select','Dropdown'],['checkbox','Consent checkbox']])}${formField('Placeholder','placeholder',f.placeholder||'')}${textareaField('Dropdown options · one per line','options',f.options||'')}${toggleField('Required field','Visitor must complete this field.','required',!!f.required)}${toggleField('Active field','Show this field on the public registration form.','active',f.active!==false)}`;
    } else if(kind==='group'){
      const arr=getGroups(groupKind),g=index==null?{name:'',active:true,weight:100}:arr[index];$('entityTitle').textContent=index==null?'Add Group':'Edit Group';$('entitySubtitle').textContent='Groups help organize content and control ordering.';html=`${formField('Group name','name',g.name,true)}${formField('Weightage','weight',g.weight,false,'number')}${toggleField('Active group','Keep this group available for assignments.','active',g.active!==false)}`;
    }
    body.innerHTML=html;modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.classList.add('wb19-modal-open');setTimeout(()=>body.querySelector('input,textarea,select')?.focus(),50)
  }
  function formField(label,name,value,required=false,type='text'){return `<label class="wb19-field"><span>${label}${required?' *':''}</span><input name="${name}" type="${type}" value="${attr(value??'')}" ${required?'required':''}></label>`}
  function textareaField(label,name,value){return `<label class="wb19-field"><span>${label}</span><textarea name="${name}">${esc(value||'')}</textarea></label>`}
  function selectField(label,name,value,options){return `<label class="wb19-field"><span>${label}</span><select name="${name}">${options.map(([v,l])=>`<option value="${attr(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`}
  function toggleField(title,sub,name,checked){return `<label class="entity-toggle-line"><div><b>${title}</b><small>${sub}</small></div><input type="checkbox" name="${name}" ${checked?'checked':''}></label>`}
  function closeEntityModal(){const m=$('entityModal');m.classList.remove('open');m.setAttribute('aria-hidden','true');document.body.classList.remove('wb19-modal-open');entityContext=null}
  function saveEntity(){const ctx=entityContext;if(!ctx)return;const fd=new FormData($('entityForm'));
    if(ctx.kind==='speaker'){const s=speakerSection();const obj=ctx.index==null?{id:uid('sp'),photo:'',weight:100}:s.speakers[ctx.index];Object.assign(obj,{name:fd.get('name'),role:fd.get('role'),company:fd.get('company'),groupId:fd.get('groupId'),status:fd.has('status')});if(ctx.index==null)s.speakers.push(obj)}
    if(ctx.kind==='agenda'){const s=sectionBy('agenda');const obj=ctx.index==null?{id:uid('ag'),time:''}:s.agenda[ctx.index];Object.assign(obj,{title:fd.get('title'),start:fd.get('start'),end:fd.get('end'),groupId:fd.get('groupId'),speakerIds:fd.getAll('speakerIds'),summary:fd.get('summary'),points:fd.get('points'),status:fd.has('status')});if(obj.start)obj.time=new Date(obj.start).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});if(ctx.index==null)s.agenda.push(obj)}
    if(ctx.kind==='gallery'){const s=sectionBy('glimpse'),obj=s.images[ctx.index];Object.assign(obj,{title:fd.get('title'),socialHandle:fd.get('socialHandle'),groupId:fd.get('groupId'),weight:Number(fd.get('weight'))||100,status:fd.has('status')})}
    if(ctx.kind==='contact'){const s=sectionBy('contact');const obj=ctx.index==null?{id:uid('ct')}:s.contacts[ctx.index];Object.assign(obj,{name:fd.get('name'),email:fd.get('email'),phone:fd.get('phone'),company:fd.get('company'),designation:fd.get('designation'),groupId:fd.get('groupId'),status:fd.has('status')});if(ctx.index==null)s.contacts.push(obj)}
    if(ctx.kind==='regfield'){const arr=state.form.customFields||(state.form.customFields=[]),obj=ctx.index==null?{id:uid('rf')}:arr[ctx.index];let key=String(fd.get('name')||fd.get('label')||'custom_field').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'');if(!key)key='custom_'+(arr.length+1);Object.assign(obj,{label:fd.get('label'),name:key,type:fd.get('type')||'text',placeholder:fd.get('placeholder')||'',options:fd.get('options')||'',required:fd.has('required'),active:fd.has('active')});if(ctx.index==null)arr.push(obj)}
    if(ctx.kind==='group'){const arr=getGroups(ctx.groupKind),obj=ctx.index==null?{id:uid(ctx.groupKind.slice(0,2)+'g')}:arr[ctx.index];Object.assign(obj,{name:fd.get('name'),weight:Number(fd.get('weight'))||100,active:fd.has('active')});if(ctx.index==null)arr.push(obj)}
    markDirty();closeEntityModal();renderEditor();renderRegistrationManager();toast('Saved')
  }

  /* Smart image studio */
  function chooseImage(options,onApply){const input=document.createElement('input');input.type='file';input.accept='image/*';input.onchange=()=>{const file=input.files?.[0];if(file)openPhotoStudio(file,options,onApply)};input.click()}
  function openPhotoStudio(file,options,onApply){const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{photoState={file,img,onApply,title:options.title||'Image Studio',aspect:options.aspect||'portrait',zoom:1,panX:0,panY:0,bgMode:'original',bgColor:'#f7f1e5',quality:.76};$('photoStudioTitle').textContent=photoState.title;$('photoAspect').value=photoState.aspect;$('photoZoom').value=100;$('photoPanX').value=0;$('photoPanY').value=0;$('photoBgMode').value='original';$('photoBgColor').value='#f7f1e5';$('photoQuality').value=76;$('photoOriginalSize').textContent=formatBytes(file.size);$('photoOutputSize').textContent='Live preview';updatePhotoLabels();renderPhotoCanvas();$('photoStudioModal').classList.add('open');$('photoStudioModal').setAttribute('aria-hidden','false');document.body.classList.add('wb19-modal-open')};img.src=reader.result};reader.readAsDataURL(file)}
  function closePhotoStudio(){const m=$('photoStudioModal');m.classList.remove('open');m.setAttribute('aria-hidden','true');document.body.classList.remove('wb19-modal-open');photoState=null}
  function aspectSize(aspect,preview=false){if(aspect==='brandfree'&&photoState?.img){const img=photoState.img,maxW=preview?640:1600,maxH=preview?420:900;const scale=preview?Math.min(maxW/img.width,maxH/img.height):Math.min(1,maxW/img.width,maxH/img.height);return[Math.max(1,Math.round(img.width*scale)),Math.max(1,Math.round(img.height*scale))]}if(aspect==='hero')return preview?[640,288]:[1600,720];if(aspect==='mobile')return preview?[384,512]:[768,1024];if(aspect==='illustration')return preview?[500,500]:[1000,1000];if(aspect==='brandhero')return preview?[571,340]:[571,340];if(aspect==='brand')return preview?[600,130]:[1200,260];if(aspect==='logo')return preview?[480,320]:[900,600];if(aspect==='seo')return preview?[600,315]:[1200,630];if(aspect==='thumbnail')return preview?[420,420]:[300,300];if(aspect==='square')return preview?[520,520]:[720,720];if(aspect==='landscape')return preview?[640,400]:[1200,750];return preview?[480,600]:[600,750]}
  function renderPhotoCanvas(final=false){if(!photoState)return;const canvas=$('photoCanvas'),[w,h]=aspectSize(photoState.aspect,!final);canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.clearRect(0,0,w,h);const isBrandFree=photoState.aspect==='brandfree',preserveAlpha=(['illustration','brandhero','logo'].includes(photoState.aspect)||isBrandFree)&&photoState.bgMode==='original';if(!preserveAlpha){ctx.fillStyle=photoState.bgColor;ctx.fillRect(0,0,w,h)}const img=photoState.img,base=isBrandFree?Math.min(w/img.width,h/img.height):Math.max(w/img.width,h/img.height),scale=base*photoState.zoom,dw=img.width*scale,dh=img.height*scale,dx=(w-dw)/2+(photoState.panX/100)*(w*.32),dy=(h-dh)/2+(photoState.panY/100)*(h*.32);ctx.drawImage(img,dx,dy,dw,dh);if(photoState.bgMode!=='original')replaceBackground(ctx,w,h,photoState.bgMode,photoState.bgColor);const mime=isBrandFree?'image/webp':preserveAlpha?'image/png':'image/jpeg';if(final){const data=mime==='image/png'?canvas.toDataURL(mime):canvas.toDataURL(mime,photoState.quality);$('photoOutputSize').textContent=formatBytes(dataUrlBytes(data));return data}requestAnimationFrame(()=>{const preview=mime==='image/png'?canvas.toDataURL(mime):canvas.toDataURL(mime,photoState.quality);$('photoOutputSize').textContent='≈ '+formatBytes(Math.round(dataUrlBytes(preview)))})}
  function replaceBackground(ctx,w,h,mode,bg){const im=ctx.getImageData(0,0,w,h),d=im.data,rgb=hexRgb(bg);for(let i=0;i<d.length;i+=4){const r=d[i],g=d[i+1],b=d[i+2],max=Math.max(r,g,b),min=Math.min(r,g,b),sat=max-min,bright=(r+g+b)/3;const remove=mode==='light'?(bright>218&&sat<42):(bright<42&&sat<34);if(remove){d[i]=rgb.r;d[i+1]=rgb.g;d[i+2]=rgb.b;d[i+3]=255}}ctx.putImageData(im,0,0)}
  function hexRgb(hex){const v=hex.replace('#','');return{r:parseInt(v.slice(0,2),16)||255,g:parseInt(v.slice(2,4),16)||255,b:parseInt(v.slice(4,6),16)||255}}
  function dataUrlBytes(s){return Math.max(0,Math.round((s.length-(s.indexOf(',')+1))*3/4))}
  function formatBytes(n){if(n<1024)return n+' B';if(n<1024*1024)return Math.round(n/1024)+' KB';return (n/1024/1024).toFixed(1)+' MB'}
  function updatePhotoLabels(){$('photoZoomValue').textContent=Math.round(photoState.zoom*100)+'%';$('photoPanXValue').textContent=photoState.panX;$('photoPanYValue').textContent=photoState.panY;$('photoQualityValue').textContent=Math.round(photoState.quality*100)+'%'}
  function applyPhoto(){if(!photoState)return;const cb=photoState.onApply,data=renderPhotoCanvas(true);cb(data);closePhotoStudio();toast('Image cropped & compressed')}
  function compressBanner(file,callback){const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const maxW=1600,maxH=1000,scale=Math.min(1,maxW/img.width,maxH/img.height),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const ctx=c.getContext('2d');ctx.drawImage(img,0,0,c.width,c.height);callback(c.toDataURL('image/jpeg',.78))};img.src=r.result};r.readAsDataURL(file)}

  function builderNavItems(){const raw=ETB2BSite.navItems?ETB2BSite.navItems(award,state,{currentPage:'home'}):[];return raw.filter(i=>i.id!=='home'||true)}
  function renderNavManager(){
    const box=$('navManager');if(!box)return;const items=builderNavItems();state.nav.order=Array.isArray(state.nav.order)?state.nav.order:[];items.forEach(i=>{if(!state.nav.order.includes(i.id))state.nav.order.push(i.id)});
    const orderMap=new Map(state.nav.order.map((id,i)=>[id,i]));items.sort((a,b)=>(orderMap.get(a.id)??999)-(orderMap.get(b.id)??999));
    box.innerHTML=items.length?items.map((i,idx)=>`<div class="nav-sort-row" draggable="true" data-nav-sort-id="${i.id}"><span class="nav-sort-handle">⠿</span><div class="nav-sort-copy"><b>${esc(i.label)}</b><small>${i.id==='home'?'Homepage':i.type==='section'?'Homepage section':'Award page'} · Position ${String(idx+1).padStart(2,'0')}</small></div><span class="nav-sort-badge">${i.type==='section'?'Section':i.type==='page'?'Page':'Home'}</span></div>`).join(''):'<div class="nav-empty">Switch on sections or award pages to build your navigation.</div>';
    let dragId=null;box.querySelectorAll('[data-nav-sort-id]').forEach(row=>{row.addEventListener('dragstart',()=>{dragId=row.dataset.navSortId;row.classList.add('dragging')});row.addEventListener('dragend',()=>{dragId=null;row.classList.remove('dragging');box.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'))});row.addEventListener('dragover',e=>{e.preventDefault();if(dragId&&dragId!==row.dataset.navSortId)row.classList.add('drag-over')});row.addEventListener('dragleave',()=>row.classList.remove('drag-over'));row.addEventListener('drop',e=>{e.preventDefault();row.classList.remove('drag-over');if(!dragId||dragId===row.dataset.navSortId)return;const activeIds=items.map(x=>x.id),from=activeIds.indexOf(dragId),to=activeIds.indexOf(row.dataset.navSortId);if(from<0||to<0)return;const [moved]=activeIds.splice(from,1);activeIds.splice(to,0,moved);const inactive=(state.nav.order||[]).filter(id=>!activeIds.includes(id));state.nav.order=[...activeIds,...inactive];markDirty();renderNavManager();toast('Navigation order updated')})});
  }
  function parsePairs(v){return String(v||'').split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const at=line.indexOf('|');return at<0?[line,'']:[line.slice(0,at).trim(),line.slice(at+1).trim()]})}
  function pageSpecificEditor(pg){
    if(pg.id==='categories')return `<div class="page-data-note"><b>Category cards are dynamic.</b><br>Names, descriptions and status come from the Categories step. Here you control the page heading and navigation copy.</div>`;
    if(pg.id==='jury')return `<div class="page-data-note"><b>Jury profiles are dynamic.</b><br>People and portraits come from Homepage → Speakers/Jury. This page automatically follows that data.</div>`;
    if(pg.id==='guidelines')return `<label class="wb19-field"><span>Guideline steps · one per line as Title | Description</span><textarea class="tall" data-page-prop="items">${esc(pg.items||'')}</textarea></label>`;
    if(pg.id==='criteria')return `<label class="wb19-field"><span>Scoring note</span><textarea data-page-prop="note">${esc(pg.note||'')}</textarea></label><div class="page-data-note">The criterion names and weights are synced from the Scoring module. Use this note for methodology, governance or jury guidance.</div>`;
    if(pg.id==='terms')return `<label class="wb19-field"><span>Policy blocks · one per line as Heading | Description</span><textarea class="tall" data-page-prop="items">${esc(pg.items||'')}</textarea></label>`;
    if(pg.id==='faq')return `<label class="wb19-field"><span>FAQs · one per line as Question | Answer</span><textarea class="tall" data-page-prop="items">${esc(pg.items||'')}</textarea></label>`;
    if(pg.id==='contact')return `<div class="page-data-note"><b>Contact directory is synced.</b><br>Edit people, emails, phone numbers and groups from Homepage → Contact. The dedicated Contact Us page uses the same directory automatically.</div>`;
    if(pg.id==='previous')return `<label class="wb19-field"><span>Previous edition story</span><textarea class="tall" data-page-prop="body">${esc(pg.body||'')}</textarea></label>`;
    if(pg.id==='rewards')return `<label class="wb19-field"><span>Reward benefits · one per line as Title | Description</span><textarea class="tall" data-page-prop="items">${esc(pg.items||'')}</textarea></label>`;
    return '';
  }
  function openPublicPageDesigner(id){const pg=pageBy(id);if(!pg)return;$('publicPageTitle').textContent=pg.label;$('publicPageSubtitle').textContent='Edit the page copy. Navigation visibility is controlled from Sections.';$('publicPagePreview').href=pageHref(pg.id);$('publicPageEditor').innerHTML=`<div class="page-editor-intro"><b>Live page controls</b><small>Changes are saved into this award website and appear on the public page after you save the draft.</small></div><label class="wb19-field"><span>Navigation label</span><input data-page-prop="navLabel" value="${attr(pg.navLabel||pg.label)}"></label><label class="wb19-field"><span>Eyebrow / kicker</span><input data-page-prop="eyebrow" value="${attr(pg.eyebrow||'')}"></label><label class="wb19-field"><span>Page title</span><input data-page-prop="title" value="${attr(pg.title||pg.label)}"></label><label class="wb19-field"><span>Intro copy</span><textarea data-page-prop="intro">${esc(pg.intro||'')}</textarea></label>${pageSpecificEditor(pg)}`;$('publicPageEditor').querySelectorAll('[data-page-prop]').forEach(el=>el.addEventListener('input',()=>{pg[el.dataset.pageProp]=el.value;if(pg.id==='rewards'){state.pages.rewards.title=pg.title;state.pages.rewards.body=pg.intro}markDirty(false);renderNavManager()}));$('publicPageModal').dataset.pageId=id;$('publicPageModal').classList.add('open');$('publicPageModal').setAttribute('aria-hidden','false');document.body.classList.add('wb19-modal-open')}
  function closePublicPageDesigner(){const m=$('publicPageModal');m.classList.remove('open');m.setAttribute('aria-hidden','true');document.body.classList.remove('wb19-modal-open')}
